:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #173d37;
  background: #eaf1e9;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #d5e6d4 0, #eaf1e9 62%);
}
.card {
  width: min(100%, 520px);
  padding: 38px;
  border: 1px solid #d4e2d5;
  border-radius: 24px;
  background: #fffefa;
  box-shadow: 0 20px 60px #1a423014, 0 3px 10px #1a42300d;
}
header { text-align: center; }
.mark {
  width: 48px;
  height: 48px;
  margin: 0 auto 17px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: #dcebdc;
  color: #246452;
  font-size: 28px;
  font-weight: 750;
}
.eyebrow { margin: 0 0 6px; color: #628275; font-size: 12px; font-weight: 750; letter-spacing: .13em; }
h1 { margin: 0; color: #173d37; font-size: clamp(30px, 8vw, 38px); letter-spacing: -.04em; line-height: 1.15; }
.intro { max-width: 360px; margin: 12px auto 28px; color: #60756d; line-height: 1.55; }
.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
label { display: block; color: #294a41; font-weight: 650; }
label span { color: #809087; font-weight: 500; }
input {
  width: 100%;
  min-height: 52px;
  margin-top: 8px;
  padding: 0 14px;
  border: 1px solid #cbd9ce;
  border-radius: 12px;
  outline: none;
  background: #fff;
  color: #173d37;
  font: inherit;
  font-size: 18px;
  transition: border-color .15s, box-shadow .15s;
}
input::placeholder { color: #a7b4ac; }
input:hover { border-color: #7caa96; }
input:focus-visible { border-color: #28745d; box-shadow: 0 0 0 4px #28745d25; }
button {
  width: 100%;
  min-height: 54px;
  margin-top: 20px;
  padding: 12px 18px;
  border: 0;
  border-radius: 12px;
  background: #246452;
  color: white;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s, transform .15s, box-shadow .15s;
}
button span { margin-left: 6px; font-size: 20px; vertical-align: -1px; }
button:hover { background: #1b5142; box-shadow: 0 5px 14px #24645230; }
button:active { transform: translateY(1px); background: #153f35; }
button:focus-visible { outline: 3px solid #e5a94b; outline-offset: 3px; }
.error { margin: 12px 0 0; color: #a43b31; font-size: 14px; line-height: 1.45; }
#result { margin-top: 26px; padding-top: 22px; border-top: 1px solid #e5ebe4; }
.change-total { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.change-total span { color: #60756d; }
.change-total strong { color: #246452; font-size: 30px; letter-spacing: -.04em; }
h2 { margin: 22px 0 10px; color: #294a41; font-size: 16px; }
.coin-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 0; padding: 0; list-style: none; }
.coin-list li { display: flex; justify-content: space-between; gap: 5px; padding: 10px 11px; border-radius: 10px; background: #f0f5ee; color: #294a41; font-size: 14px; }
.coin-list li span:last-child { color: #246452; font-weight: 750; }
.empty-result { margin: 12px 0 0; color: #60756d; }
footer { margin-top: 26px; color: #819087; text-align: center; font-size: 13px; }
[hidden] { display: none !important; }
@media (max-width: 440px) {
  body { padding: 18px 12px; }
  .card { padding: 28px 22px; border-radius: 20px; }
  .fields { grid-template-columns: 1fr; gap: 14px; }
  .coin-list { grid-template-columns: repeat(2, 1fr); }
}

const denominations = [
  { cents: 2000, label: '£20 note' },
  { cents: 1000, label: '£10 note' },
  { cents: 500, label: '£5 note' },
  { cents: 200, label: '£2 coin' },
  { cents: 100, label: '£1 coin' },
  { cents: 50, label: '50p coin' },
  { cents: 20, label: '20p coin' },
  { cents: 10, label: '10p coin' },
  { cents: 5, label: '5p coin' }
];

const form = document.querySelector('#change-form');
const priceInput = document.querySelector('#price');
const paidInput = document.querySelector('#paid');
const error = document.querySelector('#error');
const result = document.querySelector('#result');
const total = document.querySelector('#change-total');
const coinList = document.querySelector('#coin-list');
const emptyResult = document.querySelector('#empty-result');

function toCents(value) {
  const number = Number(value);
  return Math.round((number + Number.EPSILON) * 100);
}

function formatMoney(cents) {
  return `£${(cents / 100).toFixed(2)}`;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  error.hidden = true;
  result.hidden = true;
  coinList.replaceChildren();

  if (priceInput.value === '' || paidInput.value === '') {
    error.textContent = 'Enter both the price and the amount paid.';
    error.hidden = false;
    return;
  }

  const price = toCents(priceInput.value);
  const paid = toCents(paidInput.value);
  if (!Number.isFinite(price) || !Number.isFinite(paid) || price < 0 || paid < 0) {
    error.textContent = 'Enter valid, non-negative amounts.';
    error.hidden = false;
    return;
  }
  if (price % 5 !== 0 || paid % 5 !== 0) {
    error.textContent = 'Amounts must be in 5p increments.';
    error.hidden = false;
    return;
  }
  if (paid < price) {
    error.textContent = 'The amount paid must be at least the price.';
    error.hidden = false;
    return;
  }

  let change = paid - price;
  total.textContent = formatMoney(change);
  emptyResult.hidden = change !== 0;

  for (const denomination of denominations) {
    const count = Math.floor(change / denomination.cents);
    change %= denomination.cents;
    if (count > 0) {
      const item = document.createElement('li');
      const label = document.createElement('span');
      const amount = document.createElement('span');
      label.textContent = denomination.label;
      amount.textContent = `× ${count}`;
      item.append(label, amount);
      coinList.append(item);
    }
  }

  result.hidden = false;
});
